# Fetch all tasks from both projects with full details
today_goal_tasks = apis.todoist.show_tasks(project_id=280, access_token=todoist_token)
inbox_tasks = apis.todoist.show_tasks(project_id=69, access_token=todoist_token)

# Extract tasks from no_section_tasks (assuming no sections)
def extract_tasks(response):
    if isinstance(response, dict):
        return response.get('no_section_tasks', [])
    return response

tg_tasks = extract_tasks(today_goal_tasks)
in_tasks = extract_tasks(inbox_tasks)

print("Today's Goal tasks:")
for t in tg_tasks:
    print(f"ID: {t['task_id']}, Title: {t['title']}, Completed: {t['is_completed']}, Duration: {t.get('duration')} {t.get('duration_unit')}, Order: {t.get('order_index')}")

print("\nInbox tasks:")
for t in in_tasks:
    print(f"ID: {t['task_id']}, Title: {t['title']}, Completed: {t['is_completed']}, Duration: {t.get('duration')} {t.get('duration_unit')}, Order: {t.get('order_index')}")

